from collections import deque
import random

def bfs_check_from_start(adj, start, forbidden_edge=None, g=7):
    n = len(adj)
    dist = [-1] * n
    dist[start] = 0
    parent = [-1] * n
    q = deque([start])
    while q:
        u = q.popleft()
        for v in adj[u]:
            if forbidden_edge and ((u == forbidden_edge[0] and v == forbidden_edge[1]) or (u == forbidden_edge[1] and v == forbidden_edge[0])):
                continue
            if v == parent[u]: continue
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                parent[v] = u
                q.append(v)
            else:
                cycle = dist[u] + dist[v] + 1
                if cycle < g:
                    return True
    return False

def has_no_short_cycle(adj, g=7):
    for i in range(len(adj)):
        if bfs_check_from_start(adj, i, None, g):
            return False
    return True

def random_graph_with_deg(n=21, min_d=3, max_d=6, g=7, target_edges=42, max_tries=1000):
    for seed in range(max_tries):
        random.seed(seed)
        possible = [(u,v) for u in range(n) for v in range(u+1,n)]
        random.shuffle(possible)
        adj = [[] for _ in range(n)]
        added_count = 0
        for u,v in possible:
            if added_count >= target_edges:
                break
            if len(adj[u]) >= max_d or len(adj[v]) >= max_d:
                continue
            adj[u].append(v)
            adj[v].append(u)
            # quick check only local
            if bfs_check_from_start(adj, u, (u,v), g) or bfs_check_from_start(adj, v, (u,v), g):
                adj[u].pop()
                adj[v].pop()
                continue
            added_count += 1
        degs = [len(lst) for lst in adj]
        if any(d < min_d for d in degs):
            continue
        if has_no_short_cycle(adj, g):
            edge_list = sorted([(min(a,b), max(a,b)) for a in range(n) for b in adj[a] if a < b])
            return edge_list, degs
    return None, None

edges, degs = random_graph_with_deg()
print("Success:", edges is not None)
if edges:
    print("Number of edges:", len(edges))
    print("First 10 edges:", edges[:10])
    print("Degrees min/max:", min(degs), max(degs))
else:
    print("Failed to find in", 1000, "tries")
